const I=(enonce,is_correct,justification)=>({enonce,is_correct,justification});
const withInfo=(enonce,newInformation)=>!newInformation||enonce.startsWith(newInformation)?enonce:`${newInformation} ${enonce}`;
const Q=(enonce,sourceBlocks,correction_generale,items,newInformation=null)=>({enonce:withInfo(enonce,newInformation),format:"qcm",sourceBlocks,correction_generale,items:items.map((x,i)=>({...x,lettre:String.fromCharCode(65+i)})),...(newInformation?{newInformation}:{})});
const R=(enonce,reponse_attendue,sourceBlocks,correction_generale,newInformation=null)=>({enonce:withInfo(enonce,newInformation),format:"qroc",reponse_attendue,sourceBlocks,correction_generale,items:[],...(newInformation?{newInformation}:{})});

