function validateSourceBlocks(extract,content){const known=new Set((extract.blocs||[]).map(b=>b.id));const missing=[];const visit=v=>{if(!v||typeof v!=="object")return;if(Array.isArray(v)){v.forEach(visit);return;}if(Array.isArray(v.sourceBlocks))for(const id of v.sourceBlocks)if(!known.has(id))missing.push(id);for(const [k,c] of Object.entries(v))if(k!=="sourceBlocks")visit(c);};visit(content);if(missing.length)throw new Error(`Chapitre 41 : sourceBlocks inconnus : ${[...new Set(missing)].join(", ")}`);}
export function buildChapter41(extract){const result={fiche:buildFiche(),flashcards:buildFlashcards(),series:[...buildIsolatedQcm(),...buildDpQcm(),...buildIsolatedQroc(),...buildDpQroc()]};validateSourceBlocks(extract,result);return result;}
